  ChatBskyGroupAddMembers: {
    lexicon: 1,
    id: "chat.bsky.group.addMembers",
    defs: {
      main: {
        type: "procedure",
        description: "Adds members to a group. The members are added in 'request' status, so they have to accept it. This creates convo memberships.",
        errors: [
          {
            name: "AccountSuspended"
          },
          {
            name: "BlockedActor"
          },
          {
            name: "BlockedSubject"
          },
          {
            name: "ConvoLocked"
          },
          {
            name: "InsufficientRole"
          },
          {
            name: "InvalidConvo"
          },
          {
            name: "MemberLimitReached"
          },
          {
            name: "NotFollowedBySender"
          },
          {
            name: "RecipientNotFound"
          },
          {
            name: "UserForbidsGroups"
          }
        ],
        input: {
          encoding: "application/json",
          schema: {
            type: "object",
            required: ["convoId", "members"],
            properties: {
              convoId: {
                type: "string"
              },
              members: {
                type: "array",
                items: {
                  type: "string",
                  format: "did"
                },
                minLength: 1
              }
            }
          }
        },
        output: {
          encoding: "application/json",
          schema: {
            type: "object",
            required: ["convo"],
            properties: {
              convo: {
                type: "ref",
                ref: "lex:chat.bsky.convo.defs#convoView"
              },
              addedMembers: {
                type: "array",
                items: {
                  type: "ref",
                  ref: "lex:chat.bsky.actor.defs#profileViewBasic"
                }
              }
            }
          }
        }
      }
    }
  },
