              pattern: {
                type: "ref",
                ref: "lex:tools.ozone.safelink.defs#patternType"
              },
              action: {
                type: "ref",
                ref: "lex:tools.ozone.safelink.defs#actionType"
              },
              reason: {
                type: "ref",
                ref: "lex:tools.ozone.safelink.defs#reasonType"
              },
